def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    my = [h[0] for h in history]
    op = [h[1] for h in history]
    last_my = my[-1]
    last_opp = op[-1]

    opp_c = 0
    for x in op:
        if x == 'C':
            opp_c += 1

    # Consecutive rounds where we cooperated and they defected.
    cd = 0
    for i in range(n - 1, -1, -1):
        if my[i] == 'C' and op[i] == 'D':
            cd += 1
        else:
            break
    if cd >= 4:
        return 'D'

    # Streak lengths for handling persistent-defector traps.
    opp_run = 0
    if last_opp == 'D':
        for i in range(n - 1, -1, -1):
            if op[i] == 'D':
                opp_run += 1
            else:
                break

    my_run = 0
    if last_my == 'D':
        for i in range(n - 1, -1, -1):
            if my[i] == 'D':
                my_run += 1
            else:
                break

    # If our defection has not ended their defection streak, defect.
    if last_my == 'D' and last_opp == 'D' and opp_run >= my_run + 4:
        return 'D'

    # If a never-cooperating opponent defected twice after our cooperation, stop forgiving.
    if last_my == 'C' and last_opp == 'D' and opp_c == 0 and opp_run >= 2:
        return 'D'

    # Recent predictive fit. Treat the opponent as Tit-for-Tat-like only when
    # copying my last action explains their moves nearly as well as any simple model.
    start = max(1, n - 20)
    sample = 0
    acC = acD = acMY = acNMY = acOP = acNOP = 0

    for i in range(start, n):
        pm = my[i - 1]
        po = op[i - 1]
        o = op[i]
        sample += 1

        if o == 'C':
            acC += 1
        else:
            acD += 1

        if o == pm:
            acMY += 1
        else:
            acNMY += 1

        if o == po:
            acOP += 1
        else:
            acNOP += 1

    if sample == 0:
        return 'C'

    max_ac = acMY
    if acC > max_ac:
        max_ac = acC
    if acD > max_ac:
        max_ac = acD
    if acOP > max_ac:
        max_ac = acOP
    if acNMY > max_ac:
        max_ac = acNMY
    if acNOP > max_ac:
        max_ac = acNOP

    # If reciprocity is among the best explanations, cooperate and let them recover.
    if acMY == max_ac:
        # But against persistent/mostly-defective tiebreakers, punish.
        if (acD == max_ac or acOP == max_ac) and (opp_run >= 4 or opp_c * 5 < 2 * n):
            return 'D'
        return 'C'

    # Near-miss reciprocity: give very cooperative opponents benefit of the doubt.
    if max_ac - acMY == 1:
        if opp_c * 3 >= 2 * n and last_my == 'C' and last_opp == 'C':
            return 'C'
        if opp_c * 4 >= 3 * n and opp_run <= 2:
            return 'C'
        return 'D'

    # Clearly nonreactive / predictable / exploitable.
    return 'D'
